package com.nigson.commerce.engagement;
import com.nigson.commerce.security.SessionCookies;import com.nigson.shared.events.EventCodec;import com.nigson.shared.observability.WireContext;import com.nigson.shared.problem.*;import com.nigson.shared.security.ActorAssertion;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.http.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.web.bind.annotation.*;import tools.jackson.databind.JsonNode;
@RestController
@ConditionalOnProperty(name="NIGSON_SECURITY_ENABLED",havingValue="true")
public final class EngagementController {
 private final EngagementRelay relay;private final SessionCookies cookies;public EngagementController(EngagementRelay relay,SessionCookies cookies){this.relay=relay;this.cookies=cookies;}
 private ActorAssertion.Actor actor(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated()||!(a.getPrincipal() instanceof ActorAssertion.Actor v))throw new Problem.Failure(ProblemCode.AUTH_REQUIRED);return v;}
 private String header(HttpServletRequest r,String n,boolean required){var values=Collections.list(r.getHeaders(n));if(values.size()>1||required&&values.size()!=1)throw ApiValues.invalid();if(values.isEmpty())return null;String v=values.getFirst();if(v.isBlank()||v.length()>512)throw ApiValues.invalid();return v;}
 private EngagementRelay.Result execute(HttpServletRequest r,String api,String path,JsonNode body){String session=cookies.read(r);if(session==null)throw new Problem.Failure(ProblemCode.AUTH_REQUIRED);boolean read=api.equals("API-176");String key=header(r,"Idempotency-Key",!read),csrf=header(r,"X-CSRF-TOKEN",!read),match=api.equals("API-098")?header(r,"If-Match",true):null;if(match!=null&&!match.matches("\"(0|[1-9][0-9]{0,18})\""))throw ApiValues.invalid();String query=null;if(read){var values=new ArrayList<String>();r.getParameterMap().forEach((k,v)->{if(v==null||v.length!=1)throw ApiValues.invalid();values.add(java.net.URLEncoder.encode(k,java.nio.charset.StandardCharsets.UTF_8)+"="+java.net.URLEncoder.encode(v[0],java.nio.charset.StandardCharsets.UTF_8));});Collections.sort(values);query=String.join("&",values);}else if(!r.getParameterMap().isEmpty())throw ApiValues.invalid();UUID correlation=WireContext.current()==null?WireContext.correlation(null):WireContext.current().correlationId;return relay.execute(actor(),session,api,path,query,body,key,match,csrf,correlation);}
 @PostMapping(value="/api/v1/reviews",consumes="application/json",produces="application/json") public ResponseEntity<JsonNode> create(HttpServletRequest r,@RequestBody JsonNode b){var v=execute(r,"API-096","/api/v1/reviews",b);return ResponseEntity.status(v.status()).header("Cache-Control","no-store").body(v.body());}
 @PostMapping(value="/api/v1/staff/reviews/{id}/moderation",consumes="application/json",produces="application/json") public ResponseEntity<JsonNode> moderate(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode b){var uuid=ApiValues.uuid(id);var v=execute(r,"API-098","/api/v1/staff/reviews/"+uuid+"/moderation",b);return ResponseEntity.status(v.status()).header("Cache-Control","no-store").eTag(Long.toString(v.body().path("version").asLong())).body(v.body());}
 @PostMapping(value="/api/v1/staff/campaigns",consumes="application/json",produces="application/json") public ResponseEntity<JsonNode> campaign(HttpServletRequest r,@RequestBody JsonNode b){var v=execute(r,"API-108","/api/v1/staff/campaigns",b);return ResponseEntity.status(v.status()).header("Cache-Control","no-store").body(v.body());}
 @GetMapping(value="/api/v1/staff/reviews",produces="application/json") public ResponseEntity<JsonNode> queue(HttpServletRequest r){if(r.getContentLengthLong()>0)throw ApiValues.invalid();var v=execute(r,"API-176","/api/v1/staff/reviews",null);return ResponseEntity.ok().header("Cache-Control","no-store").body(v.body());}
}
